// ── 🏯 mundo-santuario-zen · Director de Escena & Atmósfera ─────────────────────────────
//
// Configura automáticamente la atmósfera visual, reflejos en agua en tiempo real,
// lluvia continua de pétalos de sakura en flor (hojas rosas flotantes) y enjambre de luciérnagas vivas.
//

// 1. Cargar librerías del ecosistema
await game.snippet("ambientes");
const P = await game.snippet("particulas-voxel");

// 2. Configuración estética inicial: Atardecer místico sobre el lago
game.entorno("ATARDECER", 0);
game.reflejoEntorno = true;
game.reflejoOndas = true;
game.reflejoPlanoY = 10.0; // Nivel de la superficie del agua

// 3. Sistema de partículas continuo: Pétalos de flor de cerezo (Sakura)
// Caen planeando suavemente con brisa horizontal y se posan / desvanecen sobre el agua y la isla
const petalosSakura = P.crea({
  grupo: 'sakura',
  porSegundo: 45,
  radio: 26,
  alto: 14,
  fondo: 20,
  fuerza: 0.8,
  grav: 1.2,                // Gravedad de pluma / pétalo
  deriva: 1.4,              // Vaivén de viento lateral
  derivaHz: 0.3,            // Frecuencia del vaivén
  dura: 14,
  desvanece: 4,
  vuelo: 18,
  posarse: true,
  muereEnFluido: false,      // Flotan sobre el lago
  colores: [
    [1.0, 0.72, 0.85],      // Rosa claro sakura
    [0.98, 0.58, 0.76],     // Rosa pétalo
    [0.92, 0.45, 0.65],     // Rosa cerezo intenso
    [1.0, 0.88, 0.94],      // Blanco rosado
    [0.85, 0.35, 0.55]      // Magenta suave
  ]
});
petalosSakura.enciende(45);

// 4. Sistema de partículas continuo: Luciérnagas vivas en movimiento orgánico
// Partículas brillantes que flotan lentamente hacia arriba y en espiral sobre el agua
const luciernagas = P.crea({
  grupo: 'luciernagas',
  porSegundo: 18,
  radio: 22,
  alto: 4,
  fondo: 15,
  fuerza: 0.4,
  grav: -0.6,               // Gravedad negativa suave: flotan hacia arriba
  deriva: 1.1,              // Movimiento zig-zag orgánico
  derivaHz: 0.45,
  dura: 8,
  desvanece: 3,
  vuelo: 12,
  posarse: false,
  colores: [
    [1.0, 0.95, 0.4],       // Amarillo cálido brillante
    [0.9, 1.0, 0.5],        // Amarillo verdoso luciérnaga
    [1.0, 0.8, 0.2],        // Ámbar cálido
    [1.0, 1.0, 0.7]         // Blanco dorado
  ]
});
luciernagas.enciende(18);

// 5. Mandos del Director y Cámara Cinemática
let cineRAF = null;
let cineActivo = false;

function toggleCamaraOrbital() {
  cineActivo = !cineActivo;
  if (!cineActivo) {
    if (cineRAF) cancelAnimationFrame(cineRAF);
    toast("🎥 Cámara libre restaurada");
    return;
  }
  toast("🎥 Cámara cinemática activa (WASD para cancelar)");
  const centro = [48, 16, 48];
  const radio = 32;
  const t0 = performance.now();

  function paso() {
    if (!cineActivo) return;
    const t = (performance.now() - t0) * 0.00018;
    mc.pos[0] = centro[0] + Math.cos(t) * radio;
    mc.pos[1] = 17 + Math.sin(t * 0.6) * 2.5;
    mc.pos[2] = centro[2] + Math.sin(t) * radio;
    const dx = centro[0] - mc.pos[0];
    const dz = centro[2] - mc.pos[2];
    mc.yaw = Math.atan2(-dx, -dz);
    mc.pitch = -0.12;
    cineRAF = requestAnimationFrame(paso);
  }
  paso();
}

window.addEventListener('keydown', (e) => {
  if (['w', 'a', 's', 'd', ' '].includes(e.key.toLowerCase()) && cineActivo) {
    cineActivo = false;
    if (cineRAF) cancelAnimationFrame(cineRAF);
  }
}, { capture: true });

// 6. Menú OSD (Tecla O)
const htmlOSD = () => '<div class="mc-osd-panel">'
  + '<div class="mc-osd-title">🏯 SANTUARIO ZEN</div>'
  + '<button class="mc-osd-btn" data-osd="HORA_ATARDECER">🌅 ATARDECER</button>'
  + '<button class="mc-osd-btn" data-osd="HORA_NOCHE">🌙 NOCHE</button>'
  + '<button class="mc-osd-btn" data-osd="HORA_NIEBLA">🌫️ NIEBLA</button>'
  + '<button class="mc-osd-btn" data-osd="REFLEJOS">✨ REFLEJOS: ' + (game.reflejoEntorno ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="PETALOS">🌸 PÉTALOS: ' + (petalosSakura.porSegundo ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="LUCIERNAGAS">🏮 LUCIÉRNAGAS: ' + (luciernagas.porSegundo ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="ORBITA">🎥 CÁMARA ORBITAL</button>'
  + '<button class="mc-osd-btn" data-osd="REC">🔴 GRABAR VÍDEO (Alt+V)</button>'
  + '<button class="mc-osd-btn">CERRAR</button>'
  + '</div>';

game.osd.define('menu_santuario', { sitio: 'abajo-derecha', showTool: false, html: htmlOSD() });

game.osd.alPulsar('HORA_ATARDECER', () => { game.entorno('ATARDECER', 2); });
game.osd.alPulsar('HORA_NOCHE', () => { game.entorno('NOCHE', 2); });
game.osd.alPulsar('HORA_NIEBLA', () => { game.entorno('NIEBLA', 2); });
game.osd.alPulsar('REFLEJOS', () => {
  game.reflejoEntorno = !game.reflejoEntorno;
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
});
game.osd.alPulsar('PETALOS', () => {
  if (petalosSakura.porSegundo) { petalosSakura.para(); petalosSakura.limpia(); }
  else { petalosSakura.enciende(45); }
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
});
game.osd.alPulsar('LUCIERNAGAS', () => {
  if (luciernagas.porSegundo) { luciernagas.para(); luciernagas.limpia(); }
  else { luciernagas.enciende(18); }
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
});
game.osd.alPulsar('ORBITA', () => {
  game.osd.cerrar();
  toggleCamaraOrbital();
});
game.osd.alPulsar('REC', () => {
  game.osd.cerrar();
  if (typeof game.video !== 'undefined') game.video();
});

game.onKey('o', () => {
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
});

toast('🏯 Santuario Zen listo · Tecla O menú de director · F foto · Alt+V vídeo', 6);
